function LoadGarages()
    local path = "servers/"..cityName..".lua"
    local newGarages = {}
    local file = LoadResourceFile(GetCurrentResourceName(), path)
    if file then
        local func, err = load(file, path, "t", _ENV)
        if func then
            func()  -- Execute to define GetGarages
            newGarages = GetGarages()  -- Call the function to get Garages
            for i=1,#newGarages do
                table.insert(Garages, newGarages[i])
            end
            print("Added "..#newGarages.." garages")
        else
            print("GetCityConfigs load error: "..tostring(err))
        end
    else
        print("GetCityConfigs: file not found -> "..path)
    end
end

LoadGarages()

